  {
    "statement": "One study found that shelterwood harvesting decreased understory richness and abundance.",
    "citations": [
      "1223"
    ]
  },
  {
    "statement": "Another study found that shelterwood harvesting had no effect on tree abundance.",
    "citations": [
      "1223"
    ]
